// Parse JWT token to extract expiration
export function parseJWT(token: string): { exp?: number; valid: boolean } {
  try {
    const parts = token.split('.');
    if (parts.length !== 3) return { valid: false };

    const payload = JSON.parse(atob(parts[1]));
    return { exp: payload.exp, valid: true };
  } catch {
    return { valid: false };
  }
}

// Build cookies.txt format from individual fields
export function buildCookiesTxt(token: string, bxUa?: string, bxUmidtoken?: string): string {
  const lines: string[] = [
    '# Netscape HTTP Cookie File',
    '# Generated by Qwen Dashboard',
  ];

  if (token) {
    lines.push(`.qwen.ai\tTRUE\t/\tTRUE\t0\ttoken\t${token}`);
  }

  if (bxUmidtoken) {
    lines.push(`.qwen.ai\tTRUE\t/\tTRUE\t0\tbx-umidtoken\t${bxUmidtoken}`);
  }

  return lines.join('\n');
}

// Parse cookies.txt to extract specific cookies
export function parseCookiesTxt(content: string): { token?: string; bxUmidtoken?: string } {
  const result: { token?: string; bxUmidtoken?: string } = {};

  const lines = content.split('\n').filter(line => line.trim() && !line.startsWith('#'));

  for (const line of lines) {
    const parts = line.split('\t');
    if (parts.length >= 7) {
      const name = parts[5].trim();
      const value = parts[6].trim();

      if (name === 'token') result.token = value;
      if (name === 'bx-umidtoken') result.bxUmidtoken = value;
    }
  }

  return result;
}

// Parse full cookie string (from DevTools) to extract values
export function parseFullCookieString(cookieString: string): { token?: string; bxUmidtoken?: string } {
  const result: { token?: string; bxUmidtoken?: string } = {};
  const input = cookieString.trim();

  // Format 1: Multi-line table from Cookies tab (tab/space separated columns)
  if (input.includes('\n') && !input.includes('Cookie:')) {
    const lines = input.split('\n').filter(l => l.trim());
    for (const line of lines) {
      const parts = line.split(/\s{2,}|\t+/);
      if (parts.length >= 2) {
        const name = parts[0].trim();
        const value = parts[1].trim();
        if (name === 'token' && value) result.token = value;
        if (name === 'bx-umidtoken' && value) result.bxUmidtoken = value;
      }
    }
    return result;
  }

  // Format 2: Full HTTP headers - extract Cookie: line
  if (input.includes('Cookie:')) {
    const cookieLine = input.split('\n').find(l => l.trim().toLowerCase().startsWith('cookie:'));
    if (cookieLine) {
      const cookieValue = cookieLine.substring(cookieLine.indexOf(':') + 1).trim();
      return parseFullCookieString(cookieValue);
    }
    return result;
  }

  // Format 3: Raw cookie string "token=xxx; bx-umidtoken=yyy"
  const cookies = input.split(';').map(c => c.trim());
  for (const cookie of cookies) {
    const [name, ...valueParts] = cookie.split('=');
    const value = valueParts.join('=').trim();
    if (name.trim() === 'token' && value) result.token = value;
    if (name.trim() === 'bx-umidtoken' && value) result.bxUmidtoken = value;
  }

  return result;
}

// Parse full headers string to extract bx-ua and bx-umidtoken
export function parseFullHeaders(headersString: string): { bxUa?: string; bxUmidtoken?: string } {
  const result: { bxUa?: string; bxUmidtoken?: string } = {};

  const lines = headersString.split('\n').map(l => l.trim()).filter(l => l);

  for (const line of lines) {
    const colonIndex = line.indexOf(':');
    if (colonIndex === -1) continue;

    const name = line.substring(0, colonIndex).trim().toLowerCase();
    const value = line.substring(colonIndex + 1).trim();

    if (name === 'bx-ua' && value) {
      result.bxUa = value;
    }
    if (name === 'bx-umidtoken' && value) {
      result.bxUmidtoken = value;
    }
  }

  return result;
}
